package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.service.content.ReportInputProfile;
import com.lianxibu.site.service.jobs.GenerationFlowService.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.transaction.*;
import org.springframework.transaction.support.*;

/** Real native report prepare/worker/APPLIED/ready/first and complete pages; source/model and current eligibility port are fictional. */
class ReportPeriodInputComponentTest {
    ReportOriginalCompletionTest h;ReportPeriodInputComponentService service;boolean valid=true,blocked;
    static final LocalDate LAST=LocalDate.parse("2026-01-04");
    static final Instant CUTOFF=LAST.plusDays(1).atTime(5,0).atZone(ZoneId.of("Asia/Shanghai")).toInstant();
    ReportOriginalCompletionTest fixture(){return new ReportOriginalCompletionTest(){@Override ResultJdbcStoreTest fixture(){var f=(NativeFixture)super.fixture();f.logicalKeyOverride="report:daily:2026-01-01";return f;}};}
    @BeforeEach void setup(){h=fixture();h.setup();h.apply();h.observe(h.now());valid=true;blocked=false;service=create(32L*1024*1024);}
    ReportPeriodInputComponentService create(long budget){return new ReportPeriodInputComponentService(h.h.f.source,h.service,v->new ReportPeriodInputComponentService.Validity(valid,blocked),h.h.f.tx,budget);}
    <T>T rr(java.util.function.Supplier<T> work){var tx=new TransactionTemplate(h.h.f.tx);tx.setReadOnly(true);tx.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);return tx.execute(s->work.get());}
    ReportPeriodInputComponentService.Captured capture(){return service.capture(Stage.WEEKLY_REPORT,LAST,CUTOFF);}
    Prepare command(Stage stage,LocalDate last){return new Prepare("report:"+stage.name().toLowerCase()+":"+last,1,stage,last,null,List.of(),List.of(),List.of(),false,"a".repeat(64));}
    @Test void ActualWholeWeekRetainsExactOriginalDailyBodyVersionAndEveryMissingDate(){var c=capture();assertEquals(1,c.originalRootCount());assertEquals(1,c.candidates().size());assertEquals(6,c.missing().size());assertTrue(c.sourceProof().complete());assertTrue(c.sourceProof().noUpdateDates().isEmpty());var candidate=c.candidates().getFirst();assertEquals(CanonicalJson.parse(ResultJdbcStoreTest.BODY),CanonicalJson.parse(candidate.evidence().bodyJson()));assertEquals(h.version.bodyHash(),candidate.evidence().bodyHash());assertEquals(h.version,ContentVersionKey.fromJson(CanonicalJson.parse(c.referenceTargets().get(candidate.evidence().id()))));assertEquals(1,c.dependencies().size());assertSame(c,rr(()->service.verifyObserved(c)));var frozen=new ReportInputSnapshotService((cmd,t)->c.sourceProof()).freeze(command(Stage.WEEKLY_REPORT,LAST),CUTOFF);assertEquals("partial",frozen.coverageState());assertTrue(frozen.hasContent());var root=CanonicalJson.parse(frozen.snapshotJson());ReportInputProfile.validated(root);assertEquals(6,root.get(ReportInputProfile.FIELD).get("coverage").get("missing_dates").size());assertEquals(1,h.h.f.sends);assertThrows(UnsupportedOperationException.class,()->c.referenceTargets().clear());assertFalse(c.toString().contains("Fictional"));}
    @Test void NaturalMonthKeepsAllThirtyUnknownDatesRatherThanCallingThemNoUpdate(){LocalDate last=LocalDate.parse("2026-01-31");Instant cutoff=last.plusDays(1).atTime(5,0).atZone(ZoneId.of("Asia/Shanghai")).toInstant();var c=service.capture(Stage.MONTHLY_REPORT,last,cutoff);assertEquals(LocalDate.parse("2026-01-01"),c.first());assertEquals(LocalDate.parse("2026-02-01"),c.end());assertEquals(30,c.missing().size());assertEquals(1,c.candidates().size());assertTrue(c.sourceProof().noUpdateDates().isEmpty());var frozen=new ReportInputSnapshotService((cmd,t)->c.sourceProof()).freeze(command(Stage.MONTHLY_REPORT,last),cutoff);assertEquals(30,CanonicalJson.parse(frozen.snapshotJson()).get(ReportInputProfile.FIELD).get("coverage").get("missing_dates").size());}
    @Test void LateFirstIsRetainedAsAnOriginalFactButCannotCrossTheRealPeriodCutoff(){h.h.f.jdbc.update("DELETE FROM jobs WHERE target_type='content_availability'");h.observe(CUTOFF.plusSeconds(1));var c=capture();assertEquals(1,c.originalRootCount());assertTrue(c.candidates().isEmpty());assertEquals(7,c.missing().size());assertTrue(c.originalByteSize()>8192);assertSame(c,rr(()->service.verifyObserved(c)));h.h.f.jdbc.update("UPDATE jobs SET state='failed' WHERE target_type='content_availability'");assertThrows(RuntimeException.class,this::capture);}
    @Test void CurrentEligibilityIsRecheckedWhileOriginalBodyRemainsImmutable(){var old=capture();valid=false;assertThrows(RuntimeException.class,()->rr(()->service.verifyObserved(old)));var fresh=capture();assertFalse(fresh.candidates().getFirst().evidence().effectiveValid());assertEquals(old.candidates().getFirst().evidence().bodyJson(),fresh.candidates().getFirst().evidence().bodyJson());valid=true;blocked=true;var denied=capture();assertTrue(denied.candidates().getFirst().evidence().blocked());h.h.f.jdbc.update("UPDATE contents SET revision=99,body_json='{}',input_job_id='fictional-current-input'");assertEquals(denied.candidates(),capture().candidates());}
    @Test void AllSeventyQueuedRootsRemainInTheWholeProofAndNewRootsInvalidateCapture(){var producer=new DailyReportRootPagesTest();producer.h=h;for(int n=0;n<70;n++)producer.queued(n,DailyReportRootPagesTest.DAY,"fictional-pending-period-"+n);var c=capture();assertEquals(71,c.originalRootCount());assertEquals(1,c.candidates().size());assertEquals(6,c.missing().size());assertSame(c,rr(()->service.verifyObserved(c)));producer.queued(71,DailyReportRootPagesTest.DAY,"fictional-new-period-root");assertThrows(RuntimeException.class,()->rr(()->service.verifyObserved(c)));assertEquals(72,capture().originalRootCount());assertEquals(1,h.h.f.sends);}
    @Test void OriginalDamageCannotFallBackToCurrentBodyAndIssuerPeriodBudgetRrAreMandatory(){var c=capture();assertThrows(RuntimeException.class,()->rr(()->create(32L*1024*1024).verifyObserved(c)));assertThrows(RuntimeException.class,()->create(1024).capture(Stage.WEEKLY_REPORT,LAST,CUTOFF));assertThrows(RuntimeException.class,()->create(1023));assertThrows(RuntimeException.class,()->service.capture(Stage.DAILY_REPORT,LAST,CUTOFF));assertThrows(RuntimeException.class,()->service.capture(Stage.WEEKLY_REPORT,LAST.minusDays(1),CUTOFF));assertThrows(RuntimeException.class,()->service.capture(Stage.WEEKLY_REPORT,LAST,CUTOFF.plusSeconds(1)));assertThrows(RuntimeException.class,()->service.verifyObserved(c));var tx=new TransactionTemplate(h.h.f.tx);tx.setReadOnly(true);tx.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);assertThrows(RuntimeException.class,()->tx.execute(s->service.verifyObserved(c)));assertThrows(RuntimeException.class,()->h.h.f.writes.execute(h.h.f.action("fictional-period-writer"),key->null,a->capture()));h.h.f.jdbc.update("UPDATE jobs SET action_payload_hash=UNHEX(?) WHERE target_type='report_result_ready'","0".repeat(64));assertThrows(RuntimeException.class,this::capture);var source=mock(javax.sql.DataSource.class);new ReportPeriodInputComponentService(source,mock(ReportOriginalCompletionService.class),v->new ReportPeriodInputComponentService.Validity(true,false),mock(PlatformTransactionManager.class));verifyNoInteractions(source);}
}
